21	namespace zvec::sqlengine {
22	
23	const std::unordered_map<QueryNodeOp, CompareOp> kOpMap_ = {
24	    {QueryNodeOp::Q_EQ, CompareOp::EQ},
25	    {QueryNodeOp::Q_NE, CompareOp::NE},
26	    {QueryNodeOp::Q_LT, CompareOp::LT},
27	    {QueryNodeOp::Q_LE, CompareOp::LE},
28	    {QueryNodeOp::Q_GT, CompareOp::GT},
29	    {QueryNodeOp::Q_GE, CompareOp::GE},
30	    {QueryNodeOp::Q_LIKE, CompareOp::LIKE},
31	    {QueryNodeOp::Q_IN, CompareOp::CONTAIN_ANY},
32	    {QueryNodeOp::Q_CONTAIN_ALL, CompareOp::CONTAIN_ALL},
33	    {QueryNodeOp::Q_CONTAIN_ANY, CompareOp::CONTAIN_ANY},
34	    {QueryNodeOp::Q_IS_NULL, CompareOp::IS_NULL},
35	    {QueryNodeOp::Q_IS_NOT_NULL, CompareOp::IS_NOT_NULL},
36	};
37	
38	Result<InvertedSearchResult::Ptr> InvertSearch::exec_invert_cond_tree(
39	    const QueryNode *query_node) {
40	  if (query_node->type() == QueryNode::QueryNodeType::LOGIC_EXPR) {
41	    if (query_node->left() != nullptr) {
42	      auto left_res = exec_invert_cond_tree(query_node->left_node());
43	      if (!left_res) {
44	        return left_res;
45	      }
46	      if (query_node->right() == nullptr) {
47	        return left_res;
48	      } else {
49	        auto right_res = exec_invert_cond_tree(query_node->right_node());
50	        if (!right_res) {
51	          return right_res;
52	        }
53	        query_node->op() == QueryNodeOp::Q_AND
54	            ? left_res.value()->AND(*right_res.value())
55	            : left_res.value()->OR(*right_res.value());
56	        return left_res;
57	      }
58	    }
59	    if (query_node->right() != nullptr) {
60	      return exec_invert_cond_tree(query_node->right_node());
61	    }
62	    return tl::make_unexpected(Status::InvalidArgument(
63	        "exec_invert_cond_tree, logic expr has no left or right node."));
64	  }
65	
66	  if (query_node->type() == QueryNode::QueryNodeType::REL_EXPR) {
67	    return exec_invert_cond_node(query_node);
68	  }
69	
70	  return tl::make_unexpected(Status::InvalidArgument(
71	      "exec_invert_cond_tree unexpected type:", query_node->op_name()));
72	}
73	
74	CompareOp InvertSearch::query_nodeop2search_op(QueryNodeOp op) {
75	  auto iter = kOpMap_.find(op);
76	  if (iter == kOpMap_.end()) {
77	    return CompareOp::NONE;
78	  }
79	  return iter->second;
80	}
81	
82	Result<InvertedSearchResult::Ptr> InvertSearch::exec_invert_cond_node(
83	    const QueryNode *invert_cond) {
84	  auto term_node = invert_cond->right();
85	
86	  // get search oper
87	  CompareOp oper = query_nodeop2search_op(invert_cond->op());
88	  if (oper == CompareOp::NONE) {
89	    return tl::make_unexpected(Status::InvalidArgument(
90	        "do_invert_scan, get search operator failed. op:",
91	        invert_cond->op_name()));
92	  }
93	
94	  bool is_array_length = false;
95	  auto *left_node = invert_cond->left_node();
96	  std::string invert_field_name;
97	  if (left_node->op() == QueryNodeOp::Q_ID) {
98	    invert_field_name = left_node->text();
99	  } else if (left_node->op() == QueryNodeOp::Q_FUNCTION_CALL) {
100	    const QueryFuncNode *func_node =
101	        dynamic_cast<const QueryFuncNode *>(left_node);
102	    const auto &func_name = func_node->get_func_name();
103	    const auto &arguments = func_node->arguments();
104	    if (func_name == kFuncArrayLength) {
105	      invert_field_name = arguments[0]->text();
106	      is_array_length = true;
107	    } else {
108	      return tl::make_unexpected(Status::InvalidArgument(
109	          "do_invert_scan, unsupported function call. func:",
110	          func_name.c_str()));
111	    }
112	  } else {
113	    return tl::make_unexpected(Status::InvalidArgument(
114	        "do_invert_scan, unsupported left node. op:", left_node->op_name()));
115	  }
116	
117	  // get field reader
118	  auto invert_reader = segment_->get_scalar_indexer(invert_field_name);
119	  if (invert_reader == nullptr) {
120	    return tl::make_unexpected(Status::InvalidArgument(
121	        "do_invert_scan, get invert column reader failed. field:",
122	        invert_field_name.c_str()));
123	  }
124	
125	  if (oper == CompareOp::IS_NULL) {
126	    auto invert_res = invert_reader->search_null();
127	    if (!invert_res) {
128	      return tl::make_unexpected(
129	          Status::InvalidArgument("invert column reader search null failed."));
130	    }
131	    return invert_res;
132	  } else if (oper == CompareOp::IS_NOT_NULL) {
133	    auto invert_res = invert_reader->search_non_null();
134	    if (!invert_res) {
135	      return tl::make_unexpected(Status::InvalidArgument(
136	          "invert column reader search not null failed."));
137	    }
138	    return invert_res;
139	  } else if (oper == CompareOp::CONTAIN_ALL || oper == CompareOp::CONTAIN_ANY) {
140	    // NOTE: IN is handled as CONTAIN_ANY
141	    QueryListNode::Ptr list_node =
142	        std::dynamic_pointer_cast<QueryListNode>(term_node);
143	    if (list_node->exclude()) {
144	      oper = oper == CompareOp::CONTAIN_ALL ? CompareOp::NOT_CONTAIN_ALL
145	                                            : CompareOp::NOT_CONTAIN_ANY;
146	    }
147	    auto invert_res =
148	        invert_reader->multi_search(list_node->to_value_list(), oper);
149	    if (!invert_res) {
150	      return tl::make_unexpected(Status::InvalidArgument(
151	          "invert column reader multi_search failed. op:", int(oper)));
152	    }
153	    return invert_res;
154	  } else if (!is_array_length) {
155	    auto invert_term = term_node->text();
156	    auto invert_res = invert_reader->search(invert_term, oper);
157	    if (!invert_res) {
158	      return tl::make_unexpected(Status::InvalidArgument(
159	          "invert column reader search failed. term:", invert_term.c_str(),
160	          " op:", invert_cond->op_name().c_str()));
161	    }
162	    return invert_res;
163	  } else {
164	    auto invert_term = term_node->text();
165	    uint32_t len = *(reinterpret_cast<const uint32_t *>(invert_term.data()));
166	    auto invert_res = invert_reader->search_array_len(len, oper);
167	    if (!invert_res) {
168	      return tl::make_unexpected(Status::InvalidArgument(
169	          "invert column reader search failed. term:", invert_term.c_str(),
170	          " op:", invert_cond->op_name().c_str()));
171	    }
172	    return invert_res;
173	  }
174	}
175	
176	
177	}  // namespace zvec::sqlengine
